-- ANZSCO 2022 unit groups (ABS, CC BY 4.0), so stored 4-digit occupation codes read as job titles.
create table if not exists public.occupation_units (
  code text primary key,
  titles text not null,     -- the 6-digit occupations in this unit group, ' / '-separated
  group_en text not null,   -- 2-digit sub-major group
  group_zh text not null
);
alter table public.occupation_units enable row level security;
revoke all on table public.occupation_units from anon, authenticated;

on conflict (code) do update set titles = excluded.titles, group_en = excluded.group_en, group_zh = excluded.group_zh;

-- Members with their occupation spelled out, for reading the table directly.
create or replace view public.household_members_readable with (security_invoker = true) as
select m.*, o.titles as occupation_titles, o.group_zh as occupation_group_zh, o.group_en as occupation_group_en
from public.household_members m
left join public.occupation_units o on o.code = m.occupation_unit;
revoke all on table public.household_members_readable from anon, authenticated;
